// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airdrop} from "../src/airdrop.sol";

contract InvMutTest is Test {
    airdrop c;
    function setUp() public { c = new airdrop(); }

    // fuzz the from address and an arbitrary uint; the important deciding input is the length-0 array
    function testFuzz_property(address from, uint256 v) public {
        // keep from non-zero to be a plausible caller/param
        vm.assume(from != address(0));

        address[] memory tosEmpty = new address[](0);

        // Call transfer with an empty array. The reference SHOULD revert; the mutant will not.
        bool ok;
        try c.transfer(from, address(0x1234), tosEmpty, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: for ANY inputs, reference reverts (ok == false). The mutant allows ok == true for some inputs.
        assertTrue(!ok);
    }
}
